<script setup lang="ts">
defineProps<{value:unknown}>();
const labels:Record<string,string>={plan_code:'方案',plan_name:'方案名称',status:'状态',phase:'处置阶段',initial_risk:'执行前风险',started_at:'开始时间',operator:'操作者',final_risk_score:'期末风险',final_water_level:'期末水位 cm',resource_cost_score:'资源指数',water_level:'水位 cm',risk_score:'风险',rainfall:'雨量 mm/h',pump_capacity:'排水能力 m³/s',leak_flow:'估算泄漏流量 m³/h',estimatedLeakFlow:'估算泄漏流量 m³/h',riskScore:'风险',serviceStatus:'供水状态',service_status:'供水状态',interrupted_buildings:'仍停水建筑',estimated_service_loss:'服务损失指数',pressure:'压力 MPa',flow:'管段流量 m³/h',pipelineId:'管段',valves:'阀门',affectedBuildings:'影响建筑',water_mae:'水位 MAE cm',risk_mae:'风险 MAE',predicted_water_level:'预测水位 cm',actual_water_level:'实际水位 cm',predicted_water:'预测水位 cm',actual_water:'实际水位 cm',predicted_risk:'预测风险',actual_risk:'实际风险',physical_water:'物理预测水位 cm',physical_risk:'物理预测风险',horizon_minutes:'时距 min',predicted_risk_score:'预测风险',actual_risk_score:'实际风险',water_error:'水位误差 cm',risk_error:'风险误差',timestamp:'记录时间',simulation_time:'仿真秒',buildingName:'建筑名称'};
function text(value:unknown){if(value===null||value===undefined)return '未记录';if(typeof value==='number')return Number.isInteger(value)?String(value):value.toFixed(3);if(typeof value==='boolean')return value?'是':'否';if(Array.isArray(value))return value.length?value.map(v=>v&&typeof v==='object'?(v.buildingName??v.buildingId??v.id??JSON.stringify(v)):String(v)).join('、'):'无';if(typeof value==='object')return JSON.stringify(value);return String(value);}
</script><template><dl v-if="value&&typeof value==='object'&&!Array.isArray(value)" class="review-record"><div v-for="(item,key) in (value as Record<string,unknown>)" :key="key"><dt>{{labels[key]??key}}</dt><dd>{{text(item)}}</dd></div></dl><span v-else>{{text(value)}}</span></template>
